#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

# Ticket #10: infraestructura GCP de Certera. Idempotente: se puede
# volver a correr y reutiliza lo que ya existe. Valores locales en .env.gcp
# (ignorado por git). Requiere gcloud, docker, openssl y curl.
cd "$(dirname "$0")/.."
ENV_FILE=".env.gcp"
REGION="us-central1"
SQL_INSTANCE="fleet-db"
DB_NAME="fleet"
DB_USER="fleet"
SERVICE="fleet-backend"
AR_REPO="fleet"

# Las respuestas se leen del teclado: con `!` en Claude Code o con stdin
# redirigido, cada pregunta recibiría una respuesta vacía.
if [[ ! -t 0 ]]; then
  echo "Corre este wizard en una terminal interactiva (no con '!' dentro de Claude Code)."
  exit 1
fi

for bin in gcloud docker openssl curl; do
  command -v "$bin" >/dev/null 2>&1 || { echo "Falta '$bin' en el PATH."; exit 1; }
done

# upsert_secret NAME VALUE crea el secreto o le agrega una versión nueva.
upsert_secret() {
  if gcloud secrets describe "$1" >/dev/null 2>&1; then
    printf '%s' "$2" | gcloud secrets versions add "$1" --data-file=- >/dev/null
  else
    printf '%s' "$2" | gcloud secrets create "$1" --replication-policy=automatic --data-file=- >/dev/null
  fi
  printf '  %s✓ secreto%s %s\n' "$GREEN" "$RESET" "$1"
}

banner "Certera · infraestructura GCP (#10)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cuenta de Google Cloud"
current=$(gcloud config get-value account 2>/dev/null || true)
say "gcloud está usando la cuenta: ${BOLD}${current:-ninguna}${RESET}"
if [[ -z "$current" ]] || ! confirm "¿Es la cuenta con la que quieres crear la infraestructura del hackathon?"; then
  step "Se abrirá el navegador para iniciar sesión con la cuenta correcta."
  gcloud auth login
fi
note "Cuenta activa: $(gcloud config get-value account 2>/dev/null)"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Proyecto y facturación"
ask GCP_PROJECT_ID "ID del proyecto (p. ej. fleet-intel-hackathon; único en todo GCP):"
if ! gcloud projects describe "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  if confirm "El proyecto $GCP_PROJECT_ID no existe. ¿Lo creo?"; then
    gcloud projects create "$GCP_PROJECT_ID" --name="Certera"
  else
    echo "Sin proyecto no se puede seguir."; exit 1
  fi
fi
gcloud config set project "$GCP_PROJECT_ID" >/dev/null
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
say ""
say "Cuentas de facturación abiertas:"
gcloud billing accounts list --filter=open=true --format="table(name.basename():label=ID,displayName:label=NOMBRE)"
note "Si no aparece ninguna, créala en la consola y vuelve a correr el wizard."
open_url "https://console.cloud.google.com/billing?project=$GCP_PROJECT_ID"
ask GCP_BILLING_ACCOUNT "Pega el ID de la cuenta de facturación (formato 0X0X0X-0X0X0X-0X0X0X):"
# Volver a vincular la misma cuenta consume cupo de proyectos de la cuenta y
# puede fallar con "billing quota exceeded"; solo se vincula si hace falta.
linked=$(gcloud billing projects describe "$GCP_PROJECT_ID" --format='value(billingAccountName)' 2>/dev/null || true)
if [[ "$linked" == "billingAccounts/$GCP_BILLING_ACCOUNT" ]]; then
  note "El proyecto ya está vinculado a $GCP_BILLING_ACCOUNT."
else
  gcloud billing projects link "$GCP_PROJECT_ID" --billing-account="$GCP_BILLING_ACCOUNT" >/dev/null
fi
write_env GCP_BILLING_ACCOUNT "$GCP_BILLING_ACCOUNT"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "APIs"
say "Se habilitan Cloud Run, Cloud SQL Admin, Secret Manager, Artifact Registry e IAM."
step "Tarda uno o dos minutos."
gcloud services enable run.googleapis.com sqladmin.googleapis.com secretmanager.googleapis.com \
  artifactregistry.googleapis.com iam.googleapis.com
printf '  %s✓ APIs habilitadas%s\n' "$GREEN" "$RESET"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Cloud SQL: Postgres 16"
if gcloud sql instances describe "$SQL_INSTANCE" >/dev/null 2>&1; then
  note "La instancia $SQL_INSTANCE ya existe; la reutilizo."
else
  say "Instancia ${BOLD}$SQL_INSTANCE${RESET}: Postgres 16, edición Enterprise, 1 vCPU, 3,75 GB, 10 GB SSD, $REGION."
  warn "Cobra por hora mientras exista (aprox. USD 1,7 por día). Bórrala al terminar el hackathon."
  confirm "¿Creo la instancia? (tarda ~10 minutos)" || { echo "Cancelado."; exit 1; }
  gcloud sql instances create "$SQL_INSTANCE" --database-version=POSTGRES_16 --edition=ENTERPRISE \
    --cpu=1 --memory=3840MiB --region="$REGION" --storage-type=SSD --storage-size=10GB
fi
gcloud sql databases describe "$DB_NAME" --instance="$SQL_INSTANCE" >/dev/null 2>&1 \
  || gcloud sql databases create "$DB_NAME" --instance="$SQL_INSTANCE"
DB_PASSWORD=$(_existing DB_PASSWORD || openssl rand -hex 24)
if gcloud sql users list --instance="$SQL_INSTANCE" --format='value(name)' | grep -qx "$DB_USER"; then
  gcloud sql users set-password "$DB_USER" --instance="$SQL_INSTANCE" --password="$DB_PASSWORD" >/dev/null
else
  gcloud sql users create "$DB_USER" --instance="$SQL_INSTANCE" --password="$DB_PASSWORD" >/dev/null
fi
CLOUDSQL_CONNECTION_NAME=$(gcloud sql instances describe "$SQL_INSTANCE" --format='value(connectionName)')
write_env DB_PASSWORD "$DB_PASSWORD"
write_env CLOUDSQL_CONNECTION_NAME "$CLOUDSQL_CONNECTION_NAME"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "PostGIS"
say "Vamos a habilitar la extensión PostGIS desde Cloud SQL Studio."
open_url "https://console.cloud.google.com/sql/instances/$SQL_INSTANCE/studio?project=$GCP_PROJECT_ID"
step "Inicia sesión en Studio con: base de datos ${BOLD}$DB_NAME${RESET}, usuario ${BOLD}$DB_USER${RESET}, autenticación integrada."
step "Contraseña (también está en $ENV_FILE): ${BOLD}$DB_PASSWORD${RESET}"
step "Abre un editor nuevo, pega esto y ejecútalo:"
say ""
say "    ${BOLD}CREATE EXTENSION IF NOT EXISTS postgis;${RESET}"
say "    ${BOLD}SELECT postgis_version();${RESET}"
say ""
step "Debe devolver una fila con la versión (p. ej. 3.4 USE_GEOS=1 …)."
until confirm "¿Viste la versión de PostGIS?"; do note "Revisa el usuario y la base, y vuelve a ejecutar."; done

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Secret Manager"
DATABASE_URL="postgresql://$DB_USER:$DB_PASSWORD@/$DB_NAME?host=/cloudsql/$CLOUDSQL_CONNECTION_NAME"
FLEET_API_KEY=$(_existing FLEET_API_KEY || openssl rand -hex 32)
upsert_secret fleet-database-url "$DATABASE_URL"
upsert_secret fleet-api-key "$FLEET_API_KEY"
write_env FLEET_API_KEY "$FLEET_API_KEY"
note "La API key la usan MCP, Zavu y el control del replay (header X-API-Key)."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Cuenta de servicio del backend"
SA="$SERVICE@$GCP_PROJECT_ID.iam.gserviceaccount.com"
gcloud iam service-accounts describe "$SA" >/dev/null 2>&1 \
  || gcloud iam service-accounts create "$SERVICE" --display-name="Fleet backend (Cloud Run)"
# Una cuenta de servicio recién creada tarda en propagarse en IAM: los
# primeros intentos de darle permisos pueden fallar con "does not exist".
for role in roles/cloudsql.client roles/secretmanager.secretAccessor; do
  for attempt in 1 2 3 4 5 6; do
    if gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" --member="serviceAccount:$SA" \
      --role="$role" --condition=None >/dev/null 2>&1; then
      printf '  %s✓%s %s → %s\n' "$GREEN" "$RESET" "$SA" "$role"
      break
    fi
    if (( attempt == 6 )); then
      echo "No se pudo asignar $role a $SA tras 6 intentos. Vuelve a correr el wizard en un minuto."
      exit 1
    fi
    note "La cuenta de servicio aún se está propagando; reintento en 10 s ($attempt/6)…"
    sleep 10
  done
done
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Imagen del backend"
gcloud artifacts repositories describe "$AR_REPO" --location="$REGION" >/dev/null 2>&1 \
  || gcloud artifacts repositories create "$AR_REPO" --repository-format=docker --location="$REGION"
IMAGE="$REGION-docker.pkg.dev/$GCP_PROJECT_ID/$AR_REPO/backend:$(git rev-parse --short HEAD)"
say "Construyo con el Docker local y subo: ${BOLD}$IMAGE${RESET}"
gcloud auth configure-docker "$REGION-docker.pkg.dev" --quiet >/dev/null
docker build --platform linux/amd64 -t "$IMAGE" backend
docker push "$IMAGE"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Cloud Run"
say "Servicio ${BOLD}$SERVICE${RESET}: 1 instancia fija (min=max=1), CPU siempre asignada, socket a Cloud SQL, acceso público."
note "Una sola instancia es deliberado: el replay vive dentro del proceso (ADR 0005)."
confirm "¿Despliego?" || { echo "Cancelado."; exit 1; }
gcloud run deploy "$SERVICE" --image="$IMAGE" --region="$REGION" --service-account="$SA" \
  --add-cloudsql-instances="$CLOUDSQL_CONNECTION_NAME" \
  --set-secrets="DATABASE_URL=fleet-database-url:latest,API_KEY=fleet-api-key:latest" \
  --min-instances=1 --max-instances=1 --no-cpu-throttling --allow-unauthenticated --port=8080
BACKEND_URL=$(gcloud run services describe "$SERVICE" --region="$REGION" --format='value(status.url)')
write_env BACKEND_URL "$BACKEND_URL"
set_var E2E_API_URL "$BACKEND_URL"
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Verificación"
say "GET $BACKEND_URL/health"
if body=$(curl -fsS --max-time 20 "$BACKEND_URL/health"); then
  printf '  %s✓ %s%s\n' "$GREEN" "$body" "$RESET"
  grep -q '"postgis"' <<<"$body" || warn "La respuesta no trae la versión de PostGIS."
else
  warn "El backend no respondió 200. Revisa los logs:"
  note "gcloud run services logs read $SERVICE --region=$REGION --limit=50"
  SKIPPED+=("/health en $BACKEND_URL no respondió 200")
fi
pause

finish
